import { Item } from '../core/entities/Item';
import { GameEvent, resolveEventMessage } from '../core/EventBus';
import { GameWorld } from '../core/GameWorld';
import { MapGeneratorRegistry } from '../core/mapgen';
import {
  LanguageCode,
  SUPPORTED_LANGUAGES,
  TRANSLATIONS,
} from '../i18n/translations';
import { CanvasRenderer } from './CanvasRenderer';
import { SpriteManager } from './SpriteManager';

export type ActiveModalType =
  | 'none'
  | 'log'
  | 'help'
  | 'inventory'
  | 'pickup'
  | 'drop'
  | 'config'
  | 'actions';

export type ActionMenuOptionId =
  | 'pickup'
  | 'inventory'
  | 'drop'
  | 'close_door'
  | 'wait'
  | 'log'
  | 'help'
  | 'config';

/**
 * Converts internal timeline ticks into the displayed turn/time counter: Math.floor(ticks / 100).
 */
export function formatDisplayTime(ticks: number): number {
  return Math.floor(ticks / 100);
}

export interface SessionTransferEntry {
  readonly name: string;
  amount: number;
}

export interface FormattedItemModalRow {
  readonly spriteKey: string;
  readonly label: string;
  readonly amount: number;
  readonly weightLabel: string;
  readonly selected: boolean;
}

export interface FormattedActionModalRow {
  readonly id: ActionMenuOptionId;
  readonly keyBadge: string;
  readonly label: string;
  readonly contextBadge: string;
  readonly selected: boolean;
}

export interface StatusHUDConfig {
  readonly characterNameEl?: HTMLElement | null;
  readonly statusSummaryEl: HTMLElement | null;
  readonly controlsContainerEl: HTMLElement | null;
  readonly bottomLogTitleEl?: HTMLElement | null;
  readonly messageLogEl: HTMLElement | null;
  readonly logModalEl?: HTMLElement | null;
  readonly logModalTitleEl?: HTMLElement | null;
  readonly logModalSubtitleEl?: HTMLElement | null;
  readonly logModalBodyEl?: HTMLElement | null;
  readonly helpModalEl?: HTMLElement | null;
  readonly helpModalTitleEl?: HTMLElement | null;
  readonly helpModalSubtitleEl?: HTMLElement | null;
  readonly helpModalTbodyEl?: HTMLElement | null;
  readonly itemModalEl?: HTMLElement | null;
  readonly itemModalTitleEl?: HTMLElement | null;
  readonly itemModalSubtitleEl?: HTMLElement | null;
  readonly itemModalBodyEl?: HTMLElement | null;
  readonly configModalEl?: HTMLElement | null;
  readonly configModalTitleEl?: HTMLElement | null;
  readonly configModalSubtitleEl?: HTMLElement | null;
  readonly configModalBodyEl?: HTMLElement | null;
  readonly actionModalEl?: HTMLElement | null;
  readonly actionModalTitleEl?: HTMLElement | null;
  readonly actionModalSubtitleEl?: HTMLElement | null;
  readonly actionModalBodyEl?: HTMLElement | null;
  readonly registry: MapGeneratorRegistry;
  readonly sprites?: SpriteManager;
  readonly initialLanguage?: LanguageCode;
  readonly onGenerateNewMap: (generatorId: string) => void;
  readonly onTileSizeChange: (tileSize: number) => void;
  readonly onLanguageChange?: (lang: LanguageCode) => void;
  readonly onModalStateChange?: () => void;
}

const TILE_SIZE_OPTIONS = [16, 24, 32, 48, 64];
const SLOW_SCROLL_STEP_PX = 28;

/**
 * Manages:
 * 1. Top Statistics Bar (Character Name defaulting to "Howard", HP, MP, Attributes, Weight, Time;
 *    without game name, player position, door status, or redundant current Tile Size text).
 * 2. Top Bar Controls: Language Selector (English / Traditional Chinese), Tile Size Selector,
 *    Map Style Selector, and New Dungeon Button.
 * 3. Bottom Log Tab showing the latest 10 localized messages on the main page.
 * 4. Large scrollable Log Modal Tab (opened with '/', scrolled with Up/Down, PageUp/PageDown, or Mouse, closed with 'Esc').
 * 5. Consolidated Controls/Help Modal Tab (opened with 'h', closed with 'Esc').
 */
export class StatusHUD {
  private readonly config: StatusHUDConfig;
  private readonly sprites: SpriteManager;
  private selectedGeneratorId: string;
  private selectedTileSize = 32;
  private currentLanguage: LanguageCode;
  private activeModal: ActiveModalType = 'none';
  private selectedItemIndex = 0;
  private selectedActionIndex = 0;
  private sessionTransfers: SessionTransferEntry[] = [];
  private actionOptionHandler?: (actionId: ActionMenuOptionId) => void;

  constructor(config: StatusHUDConfig) {
    this.config = config;
    this.sprites = config.sprites ?? new SpriteManager();
    this.selectedGeneratorId = config.registry.getDefault().id;
    this.currentLanguage = config.initialLanguage ?? 'en';
    this.buildControls();
    this.applyStaticLocalizedLabels();
  }

  public getLanguage(): LanguageCode {
    return this.currentLanguage;
  }

  public setLanguage(lang: LanguageCode): void {
    this.currentLanguage = lang;
    this.buildControls();
    this.applyStaticLocalizedLabels();
    this.config.onLanguageChange?.(lang);
  }

  public getActiveModal(): ActiveModalType {
    return this.activeModal;
  }

  public getSelectedItemIndex(): number {
    return this.selectedItemIndex;
  }

  public getSelectedActionIndex(): number {
    return this.selectedActionIndex;
  }

  public setActionOptionHandler(handler: (actionId: ActionMenuOptionId) => void): void {
    this.actionOptionHandler = handler;
  }

  public openLogModal(world: GameWorld): void {
    this.hideAllModalElements();
    this.activeModal = 'log';
    this.config.logModalEl?.classList.remove('hidden');
    this.renderLargeLogHistory(world.eventBus.getAllEvents(), true);
  }

  public openHelpModal(): void {
    this.hideAllModalElements();
    this.activeModal = 'help';
    this.applyStaticLocalizedLabels();
    this.config.helpModalEl?.classList.remove('hidden');
  }

  public openInventoryModal(world: GameWorld): void {
    this.hideAllModalElements();
    this.activeModal = 'inventory';
    this.selectedItemIndex = 0;
    this.sessionTransfers = [];
    this.config.itemModalEl?.classList.remove('hidden');
    this.renderItemModal(world);
  }

  public openPickupModal(world: GameWorld): void {
    this.hideAllModalElements();
    this.activeModal = 'pickup';
    this.selectedItemIndex = 0;
    this.sessionTransfers = [];
    this.config.itemModalEl?.classList.remove('hidden');
    this.renderItemModal(world);
  }

  public openDropModal(world: GameWorld): void {
    this.hideAllModalElements();
    this.activeModal = 'drop';
    this.selectedItemIndex = 0;
    this.sessionTransfers = [];
    this.config.itemModalEl?.classList.remove('hidden');
    this.renderItemModal(world);
  }

  public openConfigModal(): void {
    this.hideAllModalElements();
    this.activeModal = 'config';
    this.buildControls();
    this.applyStaticLocalizedLabels();
    this.config.configModalEl?.classList.remove('hidden');
  }

  public openActionModal(world: GameWorld): void {
    this.hideAllModalElements();
    this.activeModal = 'actions';
    this.selectedActionIndex = 0;
    this.applyStaticLocalizedLabels();
    this.config.actionModalEl?.classList.remove('hidden');
    this.renderActionModal(world);
  }

  public moveActionModalSelection(world: GameWorld, delta: number): void {
    if (this.activeModal !== 'actions') {
      return;
    }
    const rows = this.getFormattedActionModalRows(world);
    if (rows.length === 0) {
      return;
    }
    this.selectedActionIndex = Math.max(
      0,
      Math.min(rows.length - 1, this.selectedActionIndex + delta)
    );
    this.renderActionModal(world);
  }

  public confirmActionModalSelection(world: GameWorld): void {
    if (this.activeModal !== 'actions') {
      return;
    }
    const rows = this.getFormattedActionModalRows(world);
    if (rows.length === 0) {
      return;
    }
    const chosen = rows[this.selectedActionIndex] ?? rows[0];
    this.actionOptionHandler?.(chosen.id);
  }

  public closeModal(world?: GameWorld): boolean {
    if (this.activeModal === 'none') {
      return false;
    }
    const closingMode = this.activeModal;
    this.activeModal = 'none';
    this.hideAllModalElements();

    if (
      world &&
      (closingMode === 'pickup' || closingMode === 'drop') &&
      this.sessionTransfers.length > 0
    ) {
      const itemsSummary = this.sessionTransfers
        .map((entry) => (entry.amount > 1 ? `${entry.name} x${entry.amount}` : entry.name))
        .join(', ');
      this.sessionTransfers = [];

      if (closingMode === 'pickup') {
        world.eventBus.log(
          `${world.player.name} picked up ${itemsSummary}.`,
          'info',
          world.timeline.currentTime,
          'pickedUpItems',
          { actor: world.player.name, items: itemsSummary }
        );
      } else {
        world.eventBus.log(
          `${world.player.name} dropped ${itemsSummary}.`,
          'info',
          world.timeline.currentTime,
          'droppedItems',
          { actor: world.player.name, items: itemsSummary }
        );
      }
      world.advancePlayerTurn(100);
    } else {
      this.sessionTransfers = [];
    }

    return true;
  }

  public moveItemModalSelection(world: GameWorld, delta: number): void {
    if (
      this.activeModal !== 'inventory' &&
      this.activeModal !== 'pickup' &&
      this.activeModal !== 'drop'
    ) {
      return;
    }
    const items = this.getModalItems(world);
    if (items.length === 0) {
      this.selectedItemIndex = 0;
      return;
    }
    this.selectedItemIndex = Math.max(
      0,
      Math.min(items.length - 1, this.selectedItemIndex + delta)
    );
    this.renderItemModal(world);
  }

  public confirmItemModalSelection(world: GameWorld, transferAllStack = false): void {
    if (this.activeModal === 'pickup') {
      const groundItems = world.getItemsAt(world.player.position);
      if (groundItems.length === 0) {
        this.closeModal(world);
        return;
      }
      this.selectedItemIndex = Math.max(
        0,
        Math.min(groundItems.length - 1, this.selectedItemIndex)
      );
      const target = groundItems[this.selectedItemIndex];
      const requestedAmount = transferAllStack ? target.amount : 1;
      const res = world.pickupGroundItemAt(world.player, this.selectedItemIndex, requestedAmount);

      if (res.status === 'PICKED_UP' && res.pickedItem) {
        this.recordSessionTransfer(res.pickedItem.name, res.pickedItem.amount);
      }

      const remaining = world.getItemsAt(world.player.position);
      if (remaining.length === 0) {
        this.closeModal(world);
      } else {
        this.selectedItemIndex = Math.min(this.selectedItemIndex, remaining.length - 1);
        this.renderItemModal(world);
      }
      return;
    }

    if (this.activeModal === 'drop') {
      const invItems = world.player.inventory.getItems();
      if (invItems.length === 0) {
        this.closeModal(world);
        return;
      }
      this.selectedItemIndex = Math.max(0, Math.min(invItems.length - 1, this.selectedItemIndex));
      const target = invItems[this.selectedItemIndex];
      const requestedAmount = transferAllStack ? target.amount : 1;
      const dropped = world.dropInventoryItemAt(
        world.player,
        this.selectedItemIndex,
        requestedAmount
      );

      if (dropped) {
        this.recordSessionTransfer(dropped.name, dropped.amount);
      }

      const remaining = world.player.inventory.getItems();
      if (remaining.length === 0) {
        this.closeModal(world);
      } else {
        this.selectedItemIndex = Math.min(this.selectedItemIndex, remaining.length - 1);
        this.renderItemModal(world);
      }
    }
  }

  private hideAllModalElements(): void {
    this.config.logModalEl?.classList.add('hidden');
    this.config.helpModalEl?.classList.add('hidden');
    this.config.itemModalEl?.classList.add('hidden');
    this.config.configModalEl?.classList.add('hidden');
    this.config.actionModalEl?.classList.add('hidden');
  }

  private recordSessionTransfer(name: string, amount: number): void {
    const existing = this.sessionTransfers.find((entry) => entry.name === name);
    if (existing) {
      existing.amount += amount;
    } else {
      this.sessionTransfers.push({ name, amount });
    }
  }

  private getModalItems(world: GameWorld): readonly Item[] {
    if (this.activeModal === 'pickup') {
      return world.getItemsAt(world.player.position);
    }
    return world.player.inventory.getItems();
  }

  /**
   * Scrolls the large Log Modal slowly up (`direction = -1`) or down (`direction = 1`)
   * when pressing ArrowUp / ArrowDown.
   */
  public scrollLogModalSlow(direction: -1 | 1): void {
    const body = this.config.logModalBodyEl;
    if (!body || this.activeModal !== 'log') {
      return;
    }
    body.scrollTop = Math.max(0, body.scrollTop + direction * SLOW_SCROLL_STEP_PX);
  }

  /**
   * Scrolls the large Log Modal by one page up (`direction = -1`) or down (`direction = 1`)
   * when pressing PageUp / PageDown.
   */
  public scrollLogModalPage(direction: -1 | 1): void {
    const body = this.config.logModalBodyEl;
    if (!body || this.activeModal !== 'log') {
      return;
    }
    const pageStep = Math.max(120, Math.floor((body.clientHeight || 320) * 0.85));
    body.scrollTop = Math.max(0, body.scrollTop + direction * pageStep);
  }

  public update(world: GameWorld, renderer: CanvasRenderer, currentGeneratorId: string): void {
    this.selectedGeneratorId = currentGeneratorId;
    this.selectedTileSize = renderer.camera.tileSize;

    const t = TRANSLATIONS[this.currentLanguage];

    if (this.config.characterNameEl) {
      this.config.characterNameEl.textContent = world.player.name;
    }

    if (this.config.statusSummaryEl) {
      const p = world.player;
      const a = p.attributes;
      const s = t.stats;
      const burdenedBadge = p.stats.isBurdened ? ` [${s.burdened}]` : '';
      this.config.statusSummaryEl.textContent =
        `${s.hp}: ${p.stats.hp}/${p.stats.maxHp} | ${s.mp}: ${p.stats.mp}/${p.stats.maxMp} | ` +
        `${s.str}:${a.str} ${s.con}:${a.con} ${s.int}:${a.int} ${s.wis}:${a.wis} ${s.agi}:${a.agi} ${s.luk}:${a.luk} | ` +
        `${s.weight}: ${p.currentCarryWeight}/${p.stats.maxCarryWeight}${burdenedBadge} | ` +
        `${s.time}: ${formatDisplayTime(world.timeline.currentTime)}`;
    }

    if (this.config.messageLogEl) {
      const recent10 = world.eventBus.getRecentEvents(10);
      this.renderBottomLogMessages(this.config.messageLogEl, recent10);
    }

    if (this.activeModal === 'log') {
      this.renderLargeLogHistory(world.eventBus.getAllEvents(), false);
    } else if (
      this.activeModal === 'inventory' ||
      this.activeModal === 'pickup' ||
      this.activeModal === 'drop'
    ) {
      this.renderItemModal(world);
    } else if (this.activeModal === 'actions') {
      this.renderActionModal(world);
    }
  }

  private applyStaticLocalizedLabels(): void {
    const t = TRANSLATIONS[this.currentLanguage];

    if (this.config.bottomLogTitleEl) {
      this.config.bottomLogTitleEl.textContent = t.logUI.bottomTabTitle;
    }

    if (this.config.logModalTitleEl) {
      this.config.logModalTitleEl.textContent = t.logUI.modalTitle;
    }

    if (this.config.logModalSubtitleEl) {
      this.config.logModalSubtitleEl.textContent = t.logUI.modalSubtitle;
    }

    if (this.config.helpModalTitleEl) {
      this.config.helpModalTitleEl.textContent = t.helpUI.modalTitle;
    }

    if (this.config.helpModalSubtitleEl) {
      this.config.helpModalSubtitleEl.textContent = t.helpUI.modalSubtitle;
    }

    if (this.config.configModalTitleEl) {
      this.config.configModalTitleEl.textContent = t.topControls.configModalTitle;
    }

    if (this.config.configModalSubtitleEl) {
      this.config.configModalSubtitleEl.textContent = t.topControls.configModalSubtitle;
    }

    if (this.config.actionModalTitleEl) {
      this.config.actionModalTitleEl.textContent = t.actionModalUI.modalTitle;
    }

    if (this.config.actionModalSubtitleEl) {
      this.config.actionModalSubtitleEl.textContent = t.actionModalUI.modalSubtitle;
    }

    if (this.config.helpModalTbodyEl) {
      this.config.helpModalTbodyEl.innerHTML = '';
      for (const row of t.helpUI.rows) {
        const tr = document.createElement('tr');
        const th = document.createElement('th');
        th.textContent = row.title;
        const td = document.createElement('td');
        td.innerHTML = row.descriptionHtml;
        tr.appendChild(th);
        tr.appendChild(td);
        this.config.helpModalTbodyEl.appendChild(tr);
      }
    }
  }

  private renderBottomLogMessages(container: HTMLElement, events: readonly GameEvent[]): void {
    const t = TRANSLATIONS[this.currentLanguage];
    container.innerHTML = '';
    if (events.length === 0) {
      const emptyEl = document.createElement('div');
      emptyEl.className = 'log-entry';
      emptyEl.textContent = t.logUI.emptyBottomLog;
      container.appendChild(emptyEl);
      return;
    }

    events.forEach((ev, idx) => {
      const row = document.createElement('div');
      const isLatest = idx === events.length - 1;
      row.className = isLatest ? 'log-entry latest' : 'log-entry';

      const timeSpan = document.createElement('span');
      timeSpan.className = 'log-time';
      timeSpan.textContent = `[t=${formatDisplayTime(ev.timestamp)}]`;

      const msgSpan = document.createElement('span');
      msgSpan.textContent = resolveEventMessage(ev, this.currentLanguage);

      row.appendChild(timeSpan);
      row.appendChild(msgSpan);
      container.appendChild(row);
    });
  }

  private renderLargeLogHistory(events: readonly GameEvent[], scrollToBottom: boolean): void {
    const body = this.config.logModalBodyEl;
    if (!body) {
      return;
    }
    const t = TRANSLATIONS[this.currentLanguage];
    const previousScrollTop = body.scrollTop;
    body.innerHTML = '';

    if (events.length === 0) {
      const emptyEl = document.createElement('div');
      emptyEl.className = 'modal-log-row';
      emptyEl.textContent = t.logUI.emptyModalLog;
      body.appendChild(emptyEl);
      return;
    }

    events.forEach((ev, idx) => {
      const row = document.createElement('div');
      const isLatest = idx === events.length - 1;
      row.className = isLatest ? 'modal-log-row latest' : 'modal-log-row';
      row.textContent = `[t=${formatDisplayTime(ev.timestamp)}] ${resolveEventMessage(ev, this.currentLanguage)}`;
      body.appendChild(row);
    });

    if (scrollToBottom) {
      body.scrollTop = body.scrollHeight;
    } else {
      body.scrollTop = previousScrollTop;
    }
  }

  /**
   * Returns the localized item rows formatted as `{obj_name}: {amounts}` alongside each item's
   * `spriteKey` (`{obj_icon}`) and weight for the currently active item modal ('inventory', 'pickup', 'drop').
   */
  public getFormattedItemModalRows(world: GameWorld): FormattedItemModalRow[] {
    const t = TRANSLATIONS[this.currentLanguage];
    const items = this.getModalItems(world);
    if (items.length === 0) {
      this.selectedItemIndex = 0;
      return [];
    }
    this.selectedItemIndex = Math.max(0, Math.min(items.length - 1, this.selectedItemIndex));
    return items.map((item, idx) => {
      const localizedName = t.itemNames[item.name] ?? item.name;
      return {
        spriteKey: item.spriteKey,
        label: `${localizedName}: ${item.amount}`,
        amount: item.amount,
        weightLabel: `(${item.totalWeight} ${t.itemModalsUI.weightUnit})`,
        selected: idx === this.selectedItemIndex,
      };
    });
  }

  /**
   * Returns the localized Action Menu rows with live context badges (ground items, inventory count, open doors).
   */
  public getFormattedActionModalRows(world: GameWorld): FormattedActionModalRow[] {
    const t = TRANSLATIONS[this.currentLanguage];
    const groundCount = world.getItemsAt(world.player.position).length;
    const bagCount = world.player.inventory.getItems().length;
    const openDoorsCount = world.getAdjacentOpenDoors().length;

    const rawOptions: Array<{
      id: ActionMenuOptionId;
      keyBadge: string;
      label: string;
      contextBadge: string;
    }> = [
      {
        id: 'pickup',
        keyBadge: 'g',
        label: t.actionModalUI.pickUpLabel,
        contextBadge: t.actionModalUI.onTileBadge.replace('{count}', String(groundCount)),
      },
      {
        id: 'inventory',
        keyBadge: 'i',
        label: t.actionModalUI.inventoryLabel,
        contextBadge: t.actionModalUI.inBagBadge.replace('{count}', String(bagCount)),
      },
      {
        id: 'drop',
        keyBadge: 'd',
        label: t.actionModalUI.dropLabel,
        contextBadge: t.actionModalUI.inBagBadge.replace('{count}', String(bagCount)),
      },
      {
        id: 'close_door',
        keyBadge: 'c',
        label: t.actionModalUI.closeDoorLabel,
        contextBadge: t.actionModalUI.openNearbyBadge.replace('{count}', String(openDoorsCount)),
      },
      {
        id: 'wait',
        keyBadge: '. / Space',
        label: t.actionModalUI.waitLabel,
        contextBadge: '',
      },
      {
        id: 'log',
        keyBadge: '/',
        label: t.actionModalUI.logLabel,
        contextBadge: '',
      },
      {
        id: 'help',
        keyBadge: 'h',
        label: t.actionModalUI.helpLabel,
        contextBadge: '',
      },
      {
        id: 'config',
        keyBadge: 'Config',
        label: t.actionModalUI.configLabel,
        contextBadge: '',
      },
    ];

    this.selectedActionIndex = Math.max(
      0,
      Math.min(rawOptions.length - 1, this.selectedActionIndex)
    );

    return rawOptions.map((opt, idx) => ({
      ...opt,
      selected: idx === this.selectedActionIndex,
    }));
  }

  private renderActionModal(world: GameWorld): void {
    const rows = this.getFormattedActionModalRows(world);
    const body = this.config.actionModalBodyEl;
    if (!body) {
      return;
    }

    body.innerHTML = '';

    rows.forEach((rowInfo, idx) => {
      const row = document.createElement('div');
      row.className = rowInfo.selected ? 'action-modal-row selected' : 'action-modal-row';
      row.dataset.actionId = rowInfo.id;

      const mainGroup = document.createElement('div');
      mainGroup.className = 'action-modal-main';

      const badgeSpan = document.createElement('span');
      badgeSpan.className = 'key-badge';
      badgeSpan.textContent = rowInfo.keyBadge;

      const labelSpan = document.createElement('span');
      labelSpan.className = 'action-modal-label';
      labelSpan.textContent = rowInfo.label;

      mainGroup.appendChild(badgeSpan);
      mainGroup.appendChild(labelSpan);

      const contextSpan = document.createElement('span');
      contextSpan.className = 'action-modal-context';
      contextSpan.textContent = rowInfo.contextBadge;

      row.appendChild(mainGroup);
      row.appendChild(contextSpan);

      row.addEventListener('click', () => {
        this.selectedActionIndex = idx;
        this.actionOptionHandler?.(rowInfo.id);
      });

      body.appendChild(row);
    });
  }

  private renderItemModal(world: GameWorld): void {
    const rows = this.getFormattedItemModalRows(world);
    const body = this.config.itemModalBodyEl;
    if (!body) {
      return;
    }
    const t = TRANSLATIONS[this.currentLanguage];
    const p = world.player;
    const weightInfo = ` (${t.stats.weight}: ${p.currentCarryWeight}/${p.stats.maxCarryWeight})`;

    let titleText = t.itemModalsUI.inventoryTitle + weightInfo;
    let subtitleText = t.itemModalsUI.inventorySubtitle;
    let emptyText = t.itemModalsUI.inventoryEmpty;

    if (this.activeModal === 'pickup') {
      titleText = t.itemModalsUI.pickupTitle + weightInfo;
      subtitleText = t.itemModalsUI.pickupSubtitle;
      emptyText = t.itemModalsUI.pickupEmpty;
    } else if (this.activeModal === 'drop') {
      titleText = t.itemModalsUI.dropTitle + weightInfo;
      subtitleText = t.itemModalsUI.dropSubtitle;
      emptyText = t.itemModalsUI.dropEmpty;
    }

    if (this.config.itemModalTitleEl) {
      this.config.itemModalTitleEl.textContent = titleText;
    }
    if (this.config.itemModalSubtitleEl) {
      this.config.itemModalSubtitleEl.textContent = subtitleText;
    }

    body.innerHTML = '';

    if (rows.length === 0) {
      const emptyEl = document.createElement('div');
      emptyEl.className = 'item-modal-empty';
      emptyEl.textContent = emptyText;
      body.appendChild(emptyEl);
      return;
    }

    rows.forEach((rowInfo, idx) => {
      const row = document.createElement('div');
      row.className = rowInfo.selected ? 'item-modal-row selected' : 'item-modal-row';
      row.dataset.index = String(idx);

      const mainGroup = document.createElement('div');
      mainGroup.className = 'item-modal-main';

      const iconImg = document.createElement('img');
      iconImg.className = 'item-modal-icon';
      iconImg.dataset.spriteKey = rowInfo.spriteKey;
      const dataUrl = this.sprites.getSpriteDataUrl(rowInfo.spriteKey);
      if (dataUrl) {
        iconImg.src = dataUrl;
      }
      iconImg.alt = rowInfo.label;

      const labelSpan = document.createElement('span');
      labelSpan.className = 'item-modal-label';
      labelSpan.textContent = rowInfo.label;

      mainGroup.appendChild(iconImg);
      mainGroup.appendChild(labelSpan);

      const rightGroup = document.createElement('div');
      rightGroup.className = 'item-modal-right';

      const weightSpan = document.createElement('span');
      weightSpan.className = 'item-modal-weight';
      weightSpan.textContent = rowInfo.weightLabel;
      rightGroup.appendChild(weightSpan);

      if (
        (this.activeModal === 'pickup' || this.activeModal === 'drop') &&
        rowInfo.amount > 1
      ) {
        const allBtn = document.createElement('button');
        allBtn.type = 'button';
        allBtn.className = 'item-all-btn';
        allBtn.textContent = `[${t.itemModalsUI.transferAllButton}]`;
        allBtn.addEventListener('click', (e: MouseEvent) => {
          e.stopPropagation();
          this.selectedItemIndex = idx;
          this.confirmItemModalSelection(world, true);
          this.config.onModalStateChange?.();
        });
        rightGroup.appendChild(allBtn);
      }

      row.appendChild(mainGroup);
      row.appendChild(rightGroup);

      row.addEventListener('click', (e: MouseEvent) => {
        this.selectedItemIndex = idx;
        if (this.activeModal === 'pickup' || this.activeModal === 'drop') {
          this.confirmItemModalSelection(world, e.shiftKey);
          this.config.onModalStateChange?.();
        } else {
          this.renderItemModal(world);
        }
      });

      body.appendChild(row);
    });
  }

  private buildControls(): void {
    const t = TRANSLATIONS[this.currentLanguage];

    // Top-right of UI: render only the Config button to open the Config Modal Tab
    const topContainer = this.config.controlsContainerEl;
    if (topContainer) {
      topContainer.innerHTML = '';
      const configBtn = document.createElement('button');
      configBtn.id = 'config-btn';
      configBtn.textContent = t.topControls.configButton;
      configBtn.style.background = '#23283c';
      configBtn.style.color = '#e6e9f4';
      configBtn.style.border = '1px solid #3b4363';
      configBtn.style.borderRadius = '4px';
      configBtn.style.padding = '4px 12px';
      configBtn.style.cursor = 'pointer';
      configBtn.style.fontWeight = '600';

      configBtn.addEventListener('click', () => {
        configBtn.blur();
        this.openConfigModal();
      });
      topContainer.appendChild(configBtn);
    }

    // Inside the Config Modal Tab: render all grouped configuration items
    const configBody = this.config.configModalBodyEl;
    if (!configBody) {
      return;
    }
    configBody.innerHTML = '';

    // 1. Language Selector (English & Traditional Chinese)
    const langRow = document.createElement('div');
    langRow.className = 'config-row';
    const langLabel = document.createElement('label');
    langLabel.className = 'config-row-label';
    langLabel.htmlFor = 'language-select';
    langLabel.textContent = t.topControls.languageLabel;

    const langSelect = document.createElement('select');
    langSelect.id = 'language-select';
    langSelect.style.background = '#0f111a';
    langSelect.style.color = '#e6e9f4';
    langSelect.style.border = '1px solid #2e344e';
    langSelect.style.borderRadius = '4px';
    langSelect.style.padding = '5px 8px';

    for (const langOpt of SUPPORTED_LANGUAGES) {
      const opt = document.createElement('option');
      opt.value = langOpt.code;
      opt.textContent = langOpt.label;
      if (langOpt.code === this.currentLanguage) {
        opt.selected = true;
      }
      langSelect.appendChild(opt);
    }

    langSelect.addEventListener('change', () => {
      const newLang = langSelect.value as LanguageCode;
      langSelect.blur();
      this.setLanguage(newLang);
    });
    langRow.appendChild(langLabel);
    langRow.appendChild(langSelect);
    configBody.appendChild(langRow);

    // 2. Tile Size Selector (default 32x32, adjustable)
    const sizeRow = document.createElement('div');
    sizeRow.className = 'config-row';
    const sizeLabel = document.createElement('label');
    sizeLabel.className = 'config-row-label';
    sizeLabel.htmlFor = 'tile-size-select';
    sizeLabel.textContent = t.topControls.tileSizeLabel;

    const sizeSelect = document.createElement('select');
    sizeSelect.id = 'tile-size-select';
    sizeSelect.style.background = '#0f111a';
    sizeSelect.style.color = '#e6e9f4';
    sizeSelect.style.border = '1px solid #2e344e';
    sizeSelect.style.borderRadius = '4px';
    sizeSelect.style.padding = '5px 8px';

    for (const size of TILE_SIZE_OPTIONS) {
      const opt = document.createElement('option');
      opt.value = String(size);
      opt.textContent = `${size}×${size} px${size === 32 ? t.topControls.defaultSuffix : ''}`;
      if (size === this.selectedTileSize) {
        opt.selected = true;
      }
      sizeSelect.appendChild(opt);
    }

    sizeSelect.addEventListener('change', () => {
      const newSize = Number(sizeSelect.value);
      this.selectedTileSize = newSize;
      this.config.onTileSizeChange(newSize);
      sizeSelect.blur();
    });
    sizeRow.appendChild(sizeLabel);
    sizeRow.appendChild(sizeSelect);
    configBody.appendChild(sizeRow);

    // 3. Map Generator Strategy Selector
    const genRow = document.createElement('div');
    genRow.className = 'config-row';
    const genLabel = document.createElement('label');
    genLabel.className = 'config-row-label';
    genLabel.htmlFor = 'map-gen-select';
    genLabel.textContent = t.topControls.mapStyleLabel;

    const genSelect = document.createElement('select');
    genSelect.id = 'map-gen-select';
    genSelect.style.background = '#0f111a';
    genSelect.style.color = '#e6e9f4';
    genSelect.style.border = '1px solid #2e344e';
    genSelect.style.borderRadius = '4px';
    genSelect.style.padding = '5px 8px';

    for (const gen of this.config.registry.list()) {
      const opt = document.createElement('option');
      opt.value = gen.id;
      opt.textContent = t.mapGenerators[gen.id] ?? gen.name;
      if (gen.id === this.selectedGeneratorId) {
        opt.selected = true;
      }
      genSelect.appendChild(opt);
    }

    genSelect.addEventListener('change', () => {
      this.selectedGeneratorId = genSelect.value;
      this.config.onGenerateNewMap(this.selectedGeneratorId);
      genSelect.blur();
    });
    genRow.appendChild(genLabel);
    genRow.appendChild(genSelect);
    configBody.appendChild(genRow);

    // 4. New Dungeon Button
    const actionRow = document.createElement('div');
    actionRow.className = 'config-row';
    actionRow.style.justifyContent = 'flex-end';

    const regenBtn = document.createElement('button');
    regenBtn.id = 'new-dungeon-btn';
    regenBtn.textContent = t.topControls.newDungeonButton;
    regenBtn.style.background = '#2563eb';
    regenBtn.style.color = '#ffffff';
    regenBtn.style.border = 'none';
    regenBtn.style.borderRadius = '4px';
    regenBtn.style.padding = '6px 14px';
    regenBtn.style.cursor = 'pointer';
    regenBtn.style.fontWeight = '600';

    regenBtn.addEventListener('click', () => {
      this.config.onGenerateNewMap(this.selectedGeneratorId);
      regenBtn.blur();
    });
    actionRow.appendChild(regenBtn);
    configBody.appendChild(actionRow);
  }
}
