import { DEFAULT_TILE_SIZE, Point } from '../core/types';

export interface TileBounds {
  readonly minX: number;
  readonly maxX: number;
  readonly minY: number;
  readonly maxY: number;
}

/**
 * Manages the 2D viewport camera centered on the player's grid position
 * and converts between world tile coordinates and screen pixel coordinates.
 * Pure TypeScript with zero DOM dependencies.
 */
export class Camera {
  public viewportWidth: number;
  public viewportHeight: number;
  private _tileSize: number;

  constructor(viewportWidth = 800, viewportHeight = 600, tileSize = DEFAULT_TILE_SIZE) {
    this.viewportWidth = Math.max(1, Math.floor(viewportWidth));
    this.viewportHeight = Math.max(1, Math.floor(viewportHeight));
    this._tileSize = Math.max(8, Math.floor(tileSize));
  }

  public get tileSize(): number {
    return this._tileSize;
  }

  public setTileSize(size: number): void {
    this._tileSize = Math.min(96, Math.max(12, Math.floor(size)));
  }

  public resizeViewport(width: number, height: number): void {
    this.viewportWidth = Math.max(1, Math.floor(width));
    this.viewportHeight = Math.max(1, Math.floor(height));
  }

  /**
   * Top-left pixel offset of the player's centered tile on screen.
   */
  public getCenterTileScreenOrigin(): Point {
    return {
      x: Math.floor((this.viewportWidth - this._tileSize) / 2),
      y: Math.floor((this.viewportHeight - this._tileSize) / 2),
    };
  }

  /**
   * Converts a world grid coordinate `tilePos` into top-left canvas pixel coordinates
   * with `playerPos` anchored at the center of the screen.
   */
  public worldToScreen(tilePos: Point, playerPos: Point): Point {
    const center = this.getCenterTileScreenOrigin();
    return {
      x: (tilePos.x - playerPos.x) * this._tileSize + center.x,
      y: (tilePos.y - playerPos.y) * this._tileSize + center.y,
    };
  }

  /**
   * Converts canvas pixel coordinates `(screenX, screenY)` into the corresponding
   * world grid tile coordinate `(tileX, tileY)`.
   */
  public screenToWorld(screenX: number, screenY: number, playerPos: Point): Point {
    const center = this.getCenterTileScreenOrigin();
    const dx = Math.floor((screenX - center.x) / this._tileSize);
    const dy = Math.floor((screenY - center.y) / this._tileSize);
    return {
      x: playerPos.x + dx,
      y: playerPos.y + dy,
    };
  }

  /**
   * Returns the range of map tile coordinates visible within the current viewport bounds.
   */
  public getVisibleTileBounds(playerPos: Point, mapWidth: number, mapHeight: number): TileBounds {
    const topLeft = this.screenToWorld(0, 0, playerPos);
    const bottomRight = this.screenToWorld(this.viewportWidth, this.viewportHeight, playerPos);

    return {
      minX: Math.max(0, topLeft.x - 1),
      maxX: Math.min(mapWidth - 1, bottomRight.x + 1),
      minY: Math.max(0, topLeft.y - 1),
      maxY: Math.min(mapHeight - 1, bottomRight.y + 1),
    };
  }
}
