/**
 * Deterministic Seeded Pseudo-Random Number Generator (Mulberry32).
 * Enables reproducible procedural dungeon generation and unit testing.
 */
export class SeededRNG {
  public readonly numericSeed: number;
  private state: number;

  constructor(seed?: number | string) {
    if (typeof seed === 'number' && Number.isFinite(seed)) {
      this.numericSeed = seed >>> 0;
    } else if (typeof seed === 'string') {
      this.numericSeed = SeededRNG.hashString(seed);
    } else {
      this.numericSeed = (Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0;
    }
    this.state = this.numericSeed || 0x6d2b79f5;
  }

  public static hashString(str: string): number {
    let h = 1779033703 ^ str.length;
    for (let i = 0; i < str.length; i++) {
      h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
      h = (h << 13) | (h >>> 19);
    }
    h = Math.imul(h ^ (h >>> 16), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    return (h ^= h >>> 16) >>> 0;
  }

  /** Returns a float in [0, 1). */
  public nextFloat(): number {
    let t = (this.state += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  /** Returns an integer in [minInclusive, maxInclusive]. */
  public nextInt(minInclusive: number, maxInclusive: number): number {
    const min = Math.ceil(Math.min(minInclusive, maxInclusive));
    const max = Math.floor(Math.max(minInclusive, maxInclusive));
    return Math.floor(this.nextFloat() * (max - min + 1)) + min;
  }

  /** Returns true with the given probability in [0, 1]. */
  public chance(probability: number): boolean {
    if (probability <= 0) return false;
    if (probability >= 1) return true;
    return this.nextFloat() < probability;
  }

  /** Picks a random element from a non-empty array. */
  public pick<T>(items: readonly T[]): T {
    if (items.length === 0) {
      throw new Error('Cannot pick from an empty array');
    }
    return items[this.nextInt(0, items.length - 1)];
  }

  /** Returns a new shuffled copy of the array (Fisher-Yates). */
  public shuffle<T>(items: readonly T[]): T[] {
    const result = [...items];
    for (let i = result.length - 1; i > 0; i--) {
      const j = this.nextInt(0, i);
      const tmp = result[i];
      result[i] = result[j];
      result[j] = tmp;
    }
    return result;
  }
}
