import { GameWorld } from './GameWorld';
import { ALL_DIRECTIONS, DoorState, Point, pointsEqual, TileType, VisibilityState } from './types';

interface AStarNode {
  readonly point: Point;
  readonly g: number;
  readonly f: number;
}

function pointKey(pt: Point): string {
  return `${pt.x},${pt.y}`;
}

/**
 * Admissible 8-way heuristic with cardinal tie-breaking:
 * - Cardinal steps cost 1.0
 * - Diagonal steps cost 1.001 (so equal-turn paths prefer clean straight lines over zig-zags)
 */
function octileTieBreakHeuristic(a: Point, b: Point): number {
  const dx = Math.abs(a.x - b.x);
  const dy = Math.abs(a.y - b.y);
  const diag = Math.min(dx, dy);
  const straight = Math.max(dx, dy) - diag;
  return straight * 1.0 + diag * 1.001;
}

function isKnownClosedDoor(world: GameWorld, pt: Point): boolean {
  const tile = world.map.getTile(pt.x, pt.y);
  if (!tile || tile.type !== TileType.DOOR) {
    return false;
  }
  const effectiveDoorState =
    tile.visibility === VisibilityState.VISIBLE ? tile.doorState : tile.lastSeenDoorState;
  return effectiveDoorState === DoorState.CLOSED;
}

function isTileTraversableForPath(
  world: GameWorld,
  pt: Point,
  isGoal: boolean
): boolean {
  if (!world.map.inBounds(pt.x, pt.y)) {
    return false;
  }
  const tile = world.map.getTile(pt.x, pt.y);
  if (!tile || tile.visibility === VisibilityState.UNEXPLORED) {
    return false;
  }
  if (tile.type === TileType.WALL) {
    return false;
  }
  // If a visible living actor blocks the tile, do not route through it
  if (world.isTileVisible(pt)) {
    const blocker = world.getBlockingActorAt(pt);
    if (blocker && !blocker.isPlayer) {
      return false;
    }
  }
  // Both FLOOR and DOOR (OPEN or CLOSED) are valid path targets/steps
  return tile.type === TileType.FLOOR || tile.type === TileType.DOOR || isGoal;
}

/**
 * Computes the 8-way shortest path from `start` to `goal` through known (`VISIBLE` or `EXPLORED`) tiles.
 * - Returns `[]` if `start` equals `goal`.
 * - Returns an array of step coordinates `[step1, step2, ..., goal]` (excluding `start`, including `goal`) if reachable.
 * - Returns `null` if `goal` is `UNEXPLORED`, a `WALL`, out of bounds, or unreachable through known tiles.
 */
export function findShortestPath(
  world: GameWorld,
  start: Point,
  goal: Point
): Point[] | null {
  if (!world.map.inBounds(start.x, start.y) || !world.map.inBounds(goal.x, goal.y)) {
    return null;
  }

  if (pointsEqual(start, goal)) {
    return [];
  }

  if (!isTileTraversableForPath(world, goal, true)) {
    return null;
  }

  const openList: AStarNode[] = [
    {
      point: start,
      g: 0,
      f: octileTieBreakHeuristic(start, goal),
    },
  ];
  const gScore = new Map<string, number>([[pointKey(start), 0]]);
  const cameFrom = new Map<string, Point>();
  const closedSet = new Set<string>();

  while (openList.length > 0) {
    // Pop node with lowest f score
    let bestIdx = 0;
    for (let i = 1; i < openList.length; i++) {
      if (openList[i].f < openList[bestIdx].f) {
        bestIdx = i;
      }
    }
    const current = openList.splice(bestIdx, 1)[0];
    const currentKey = pointKey(current.point);

    if (pointsEqual(current.point, goal)) {
      const path: Point[] = [];
      let trace: Point | undefined = current.point;
      while (trace && !pointsEqual(trace, start)) {
        path.push(trace);
        trace = cameFrom.get(pointKey(trace));
      }
      path.reverse();
      return path;
    }

    if (closedSet.has(currentKey)) {
      continue;
    }
    closedSet.add(currentKey);

    for (const dir of ALL_DIRECTIONS) {
      const next: Point = {
        x: current.point.x + dir.dx,
        y: current.point.y + dir.dy,
      };
      const nextKey = pointKey(next);

      if (closedSet.has(nextKey)) {
        continue;
      }

      const isGoal = pointsEqual(next, goal);
      if (!isTileTraversableForPath(world, next, isGoal)) {
        continue;
      }

      const isDiagonal = dir.dx !== 0 && dir.dy !== 0;
      let stepCost = isDiagonal ? 1.001 : 1.0;

      // Intermediate closed doors require 1 extra turn to open before stepping onto them
      if (!isGoal && isKnownClosedDoor(world, next)) {
        stepCost += 1.0;
      }

      const tentativeG = current.g + stepCost;
      const existingG = gScore.get(nextKey);

      if (existingG === undefined || tentativeG < existingG) {
        cameFrom.set(nextKey, current.point);
        gScore.set(nextKey, tentativeG);
        const f = tentativeG + octileTieBreakHeuristic(next, goal);
        openList.push({ point: next, g: tentativeG, f });
      }
    }
  }

  return null;
}
