/**
 * Centralized Display Words & Localization Catalog (`src/i18n/translations.ts`)
 *
 * All UI labels, top-bar controls, map generator names, modal headers,
 * control instructions, item names, and log message templates are grouped here
 * so they are easy to review and translate into additional languages.
 */

export type LanguageCode = 'en' | 'zh-TW';

export interface LanguageOption {
  readonly code: LanguageCode;
  readonly label: string;
}

export const SUPPORTED_LANGUAGES: readonly LanguageOption[] = [
  { code: 'en', label: 'English' },
  { code: 'zh-TW', label: '繁體中文 (Traditional Chinese)' },
];

export type LogMessageKey =
  | 'enteredDungeon'
  | 'waits'
  | 'moveOutsideBoundary'
  | 'blockedByWall'
  | 'blockingTheWay'
  | 'seesItemsHere'
  | 'nothingToPickUp'
  | 'inventoryEmpty'
  | 'tooHeavyToCarry'
  | 'pickedUpItems'
  | 'droppedItems'
  | 'doorTooFar'
  | 'noDoorThere'
  | 'doorAlreadyOpen'
  | 'opensDoor'
  | 'doorAlreadyClosed'
  | 'doorBlockedByEntity'
  | 'closesDoor'
  | 'noOpenDoorNearby'
  | 'multipleOpenDoorsNearby'
  | 'canceledClosingDoor'
  | 'clickAdjacentTileHint';

export interface ControlInstructionRow {
  readonly title: string;
  readonly descriptionHtml: string;
}

export interface TranslationCatalog {
  readonly languageName: string;

  // 1. Top Statistics Bar Labels
  readonly stats: {
    readonly hp: string;
    readonly mp: string;
    readonly str: string;
    readonly con: string;
    readonly int: string;
    readonly wis: string;
    readonly agi: string;
    readonly luk: string;
    readonly weight: string;
    readonly burdened: string;
    readonly time: string;
  };

  // 2. Top-Right Config Button & Config Modal Tab Controls
  readonly topControls: {
    readonly configButton: string;
    readonly configModalTitle: string;
    readonly configModalSubtitle: string;
    readonly languageLabel: string;
    readonly tileSizeLabel: string;
    readonly defaultSuffix: string;
    readonly mapStyleLabel: string;
    readonly newDungeonButton: string;
  };

  // 3. Map Generator Display Names
  readonly mapGenerators: Record<string, string>;

  // 4. Entity / Item Display Names
  readonly itemNames: Record<string, string>;

  // 5. Bottom Log Tab & Large Log Modal ('/')
  readonly logUI: {
    readonly bottomTabTitle: string;
    readonly emptyBottomLog: string;
    readonly modalTitle: string;
    readonly modalSubtitle: string;
    readonly emptyModalLog: string;
  };

  // 6. Inventory ('i'), Pick Up ('g'), and Drop ('d') Modal Tabs
  readonly itemModalsUI: {
    readonly inventoryTitle: string;
    readonly inventorySubtitle: string;
    readonly inventoryEmpty: string;
    readonly pickupTitle: string;
    readonly pickupSubtitle: string;
    readonly pickupEmpty: string;
    readonly dropTitle: string;
    readonly dropSubtitle: string;
    readonly dropEmpty: string;
    readonly weightUnit: string;
    readonly transferAllButton: string;
  };

  // 7. Action Menu Modal Tab ('Esc' / Right-Click on main screen)
  readonly actionModalUI: {
    readonly modalTitle: string;
    readonly modalSubtitle: string;
    readonly pickUpLabel: string;
    readonly inventoryLabel: string;
    readonly dropLabel: string;
    readonly closeDoorLabel: string;
    readonly waitLabel: string;
    readonly logLabel: string;
    readonly helpLabel: string;
    readonly configLabel: string;
    readonly onTileBadge: string;
    readonly inBagBadge: string;
    readonly openNearbyBadge: string;
  };

  // 8. Consolidated Controls / Help Modal ('h')
  readonly helpUI: {
    readonly modalTitle: string;
    readonly modalSubtitle: string;
    readonly rows: readonly ControlInstructionRow[];
  };

  // 9. Gameplay & Action Log Message Templates
  readonly logTemplates: Record<LogMessageKey, string>;
}

