import { DungeonMap, Rect } from '../DungeonMap';
import { Point } from '../types';

export interface MapGenConfig {
  readonly width: number;
  readonly height: number;
  readonly seed?: number | string;
  readonly doorChance?: number;
  readonly maxRooms?: number;
  readonly minRoomSize?: number;
  readonly maxRoomSize?: number;
}

export const DEFAULT_MAP_GEN_CONFIG: Required<Omit<MapGenConfig, 'seed'>> = {
  width: 49,
  height: 35,
  doorChance: 0.75,
  maxRooms: 12,
  minRoomSize: 5,
  maxRoomSize: 9,
};

export interface GeneratedDungeon {
  readonly map: DungeonMap;
  readonly playerSpawn: Point;
  readonly rooms: readonly Rect[];
  readonly candidateSpawns: readonly Point[];
  readonly generatorId: string;
  readonly seed: number;
}

/**
 * Strategy interface for dynamic dungeon map generation.
 * New map generation algorithms can be added by implementing this interface
 * and registering with MapGeneratorRegistry.
 */
export interface MapGenerator {
  readonly id: string;
  readonly name: string;
  readonly description: string;
  generate(config?: Partial<MapGenConfig>): GeneratedDungeon;
}

export class MapGeneratorRegistry {
  private readonly generators = new Map<string, MapGenerator>();
  private defaultGeneratorId: string | null = null;

  public register(generator: MapGenerator, isDefault = false): void {
    this.generators.set(generator.id, generator);
    if (isDefault || this.defaultGeneratorId === null) {
      this.defaultGeneratorId = generator.id;
    }
  }

  public get(id: string): MapGenerator {
    const gen = this.generators.get(id);
    if (!gen) {
      throw new Error(`Unknown MapGenerator id: "${id}"`);
    }
    return gen;
  }

  public getDefault(): MapGenerator {
    if (!this.defaultGeneratorId) {
      throw new Error('No MapGenerators registered in MapGeneratorRegistry');
    }
    return this.get(this.defaultGeneratorId);
  }

  public list(): MapGenerator[] {
    return Array.from(this.generators.values());
  }
}
